// Build the EZAI brand client bundle in the dsh ModuleLoader handoff format:
//   window.__ModuleLoader__.load({ id: "<name>", factory: (require) => { ... return module.exports; } });
//
// The brand artwork is generated first: the repository-owned EZAI raster is
// embedded in build/tray-icon.svg (produced from build/app-icon.png by
// scripts/generate-tray-icons.mjs). Extracting that data URI here keeps one
// source of truth for the artwork across tray, window, and client branding.
import { build } from 'esbuild'
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const packageRoot = fileURLToPath(new URL('.', import.meta.url))
const trayIconPath = fileURLToPath(new URL('../../build/tray-icon.svg', import.meta.url))

const BRAND_ARTWORK = 'data:image/png;base64,'
const source = readFileSync(trayIconPath, 'utf8')
if (!source.includes(BRAND_ARTWORK) || /<style\b/iu.test(source)) {
  throw new Error('dsh-ezai-brand: build/tray-icon.svg must embed the repository-owned EZAI artwork')
}
const match = /data:image\/png;base64,[A-Za-z0-9+/=]+/u.exec(source)
if (match === null) {
  throw new Error('dsh-ezai-brand: could not extract the EZAI artwork data URI from build/tray-icon.svg')
}

writeFileSync(
  new URL('./src/client/artwork.ts', import.meta.url),
  '// Generated by build.mjs from dsh-plugin-desktop/build/tray-icon.svg — do not edit.\n'
    + `export const EZAI_MARK_DATA_URI = '${match[0]}'\n`,
)

const pkg = JSON.parse(readFileSync(new URL('./package.json', import.meta.url), 'utf8'))

await build({
  entryPoints: ['src/client/index.tsx'],
  bundle: true,
  format: 'cjs',
  platform: 'browser',
  target: ['es2020'],
  charset: 'utf8',
  outfile: 'lib/client.js',
  jsx: 'automatic',
  // External packages are resolved through the factory's `require` at runtime,
  // mirroring how the official client modules load third-party bundles.
  external: ['react', 'react-dom', 'react-dom/client', '@deepseek-ai/dsh-client-ui-primitives', '@deepseek-ai/dsh-client-ui-slots'],
  banner: {
    js: `window.__ModuleLoader__.load({ id: ${JSON.stringify(pkg.name)}, factory: (require) => { var module = { exports: {} }; var exports = module.exports;`,
  },
  footer: {
    js: 'return module.exports; } });',
  },
  sourcemap: true,
  logLevel: 'info',
})

console.log(`dsh-ezai-brand: bundled client with EZAI artwork (${match[0].length} chars data URI)`)
